// GHIW-50: Initialize & Validate Cross-Workflow Envelope
// Validates input against envelope schema. Produces deterministic validation result.

const SCHEMA_VERSION = '1.0';
const PROJECT_ID = 'ghiw-n8n-ops-control-plane';
const ALLOWED_TASK_IDS = ['GHIW-00','GHIW-10','GHIW-50','GHIW-60','GHIW-70','GHIW-90','N8N-OPS-01','N8N-OPS-02','N8N-OPS-03','N8N-OPS-04'];
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const SHA256_RE = /^[a-f0-9]{64}$/;

const input = ($input.first().json.body || $input.first().json);

// Required field check
if (!input.schema_version) return [{ json: { decision: 'REJECTED_INVALID_SCHEMA', reason_codes: ['MISSING_SCHEMA_VERSION'], timestamp: new Date().toISOString() } }];
if (input.schema_version !== SCHEMA_VERSION) return [{ json: { decision: 'REJECTED_INVALID_SCHEMA', reason_codes: ['INVALID_SCHEMA_VERSION'], timestamp: new Date().toISOString() } }];
if (!input.run_id || !UUID_RE.test(input.run_id)) return [{ json: { decision: 'REJECTED_MISSING_FIELD', reason_codes: ['INVALID_RUN_ID'], timestamp: new Date().toISOString() } }];
if (!input.task_id || !ALLOWED_TASK_IDS.includes(input.task_id)) return [{ json: { decision: 'REJECTED_MISSING_FIELD', reason_codes: ['INVALID_TASK_ID'], timestamp: new Date().toISOString() } }];
if (!input.decision) return [{ json: { decision: 'REJECTED_MISSING_FIELD', reason_codes: ['MISSING_DECISION'], timestamp: new Date().toISOString() } }];

// Normalize input
const envelope = {
  schema_version: SCHEMA_VERSION,
  project_id: PROJECT_ID,
  run_id: input.run_id,
  task_id: input.task_id,
  parent_run_id: input.parent_run_id || null,
  source: input.source || { type: 'subworkflow', id: input.run_id },
  workflow: input.workflow || { logical_id: input.task_id, id: $workflow.id, name: $workflow.name },
  execution: input.execution || { id: $execution.id, started_at: new Date().toISOString() },
  decision: input.decision,
  reason_codes: Array.isArray(input.reason_codes) ? input.reason_codes : [],
  evidence_refs: Array.isArray(input.evidence_refs) ? input.evidence_refs : [],
  evidence_manifest_sha256: input.evidence_manifest_sha256 || null,
  classification: input.classification || 'GREEN',
  input_hash: input.input_hash || null,
  output_hash: null,
  timestamp: new Date().toISOString(),
  hermes: input.hermes || {}
};

// Compute input hash (simple deterministic hash of sorted JSON keys)
function simpleHash(s) {
  let h = 0;
  for (let i = 0; i < s.length; i++) {
    h = ((h << 5) - h) + s.charCodeAt(i);
    h |= 0;
  }
  return ('00000000' + (h >>> 0).toString(16)).slice(-8);
}

const sortedInput = JSON.stringify(envelope, Object.keys(envelope).sort());
envelope.input_hash = simpleHash(sortedInput);

return [{ json: envelope }];

// GHIW-50: Check Idempotency
// Query evidence_ledger.sqlite3 for existing run_id.
// Returns IDEMPOTENT_REPLAY if already recorded, else allows INSERT.

const state = $input.first().json;

// Build an SSH command to query the ledger.
// Since we're in n8n Code node, we prepare the command for the next SSH node.
// The actual DB query happens via SSH to Proxmox host.

function toBase64Url(s) {
  // Simple base64url encoding
  const b64 = Buffer.from ? Buffer.from(s).toString('base64') : btoa(unescape(encodeURIComponent(s)));
  return b64.replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

// Prepare ledger health/inspect command
const queryJson = JSON.stringify({
  schema_version: '1.0',
  operation: 'check-run',
  run_id: state.run_id
});

const command = 'ghiw-ledger-v1 check-run ' + toBase64Url(queryJson);

state.command = command;
state.ledger_state = 'CHECKING';

return [{ json: state }];

// GHIW-50: Write Ledger Record
// Build INSERT statement for evidence_ledger.sqlite3.
// This prepares the SQL payload for SSH execution against the Proxmox host.

const state = $input.first().json;

// For idempotency: if previous node detected existing record, skip
if (state.decision === 'IDEMPOTENT_REPLAY') {
  state.ledger_state = 'IDEMPOTENT';
  state.ledger_entry_id = state.existing_entry_id || state.run_id;
  return [{ json: state }];
}

// Build INSERT payload
function toBase64Url(s) {
  const b64 = Buffer.from ? Buffer.from(s).toString('base64') : btoa(unescape(encodeURIComponent(s)));
  return b64.replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

const insertPayload = JSON.stringify({
  schema_version: '1.0',
  run_id: state.run_id,
  task_id: state.task_id,
  parent_run_id: state.parent_run_id,
  source_type: state.source.type,
  source_id: state.source.id || '',
  workflow_id: state.workflow.id,
  execution_id: state.execution.id,
  decision: state.decision,
  reason_codes: state.reason_codes,
  classification: state.classification,
  input_hash: state.input_hash,
  evidence_refs: state.evidence_refs,
  evidence_manifest_sha256: state.evidence_manifest_sha256,
  hermes_run_id: (state.hermes.run || {}).id || '',
  hermes_task_id: (state.hermes.task || {}).id || '',
  timestamp: state.timestamp
});

state.command = 'ghiw-ledger-v1 insert ' + toBase64Url(insertPayload);
state.ledger_state = 'WRITING';

return [{ json: state }];

// GHIW-50: Assemble Ledger Receipt
// Produces the deterministic output contract for the Evidence Ledger.

const state = $input.first().json;

// Compute output hash
function simpleHash(s) {
  let h = 0;
  for (let i = 0; i < s.length; i++) {
    h = ((h << 5) - h) + s.charCodeAt(i);
    h |= 0;
  }
  return ('00000000' + (h >>> 0).toString(16)).slice(-8);
}

const receipt = {
  schema_version: '1.0',
  project_id: state.project_id,
  run_id: state.run_id,
  task_id: state.task_id,
  source: state.source,
  workflow: state.workflow,
  execution: { ...state.execution, completed_at: new Date().toISOString() },
  decision: state.ledger_state === 'IDEMPOTENT' ? 'IDEMPOTENT_REPLAY' : 'RECORDED',
  reason_codes: state.ledger_state === 'IDEMPOTENT' ? ['IDEMPOTENT_REPLAY', 'RUN_ALREADY_RECORDED'] : ['RUN_RECORDED'],
  evidence_refs: state.evidence_refs || [],
  evidence_manifest_sha256: state.evidence_manifest_sha256,
  classification: state.ledger_state === 'WRITING' ? 'GREEN' : 'AMBER',
  input_hash: state.input_hash,
  output_hash: simpleHash(JSON.stringify(state)),
  ledger_entry_id: state.run_id,
  timestamp: new Date().toISOString()
};

return [{ json: receipt }];
